document.addEventListener("DOMContentLoaded",()=>{let e=document.querySelectorAll('[data-copy="link"]');if(0===e.length){return}e.forEach(e=>{let t=e.querySelector('[data-copy="clicked"]');if(!t){console.warn('Внутри элемента с data-copy="link" не найден data-copy="clicked"');return}e.addEventListener("click",async()=>{let e=window.location.href;try{await navigator.clipboard.writeText(e),t.style.display="block",clearTimeout(t._hideTimer),t._hideTimer=setTimeout(()=>{t.style.display="none"},5e3)}catch(a){console.error("Не удалось скопировать ссылку:",a)}})})});